{"events":[{"t_s":<segundos en el eje de tiempo de PlotJuggler>,"kind":"<etiqueta corta en inglés>","detail":"<texto breve>","source":"<topic/campo>"}],"values":{"<nombre>":{"value":<número>,"unit":"<unidad>","source":"<topic/campo>"}},"assumptions":["<cada suposición o elección que hayas hecho, o lo que no pudiste determinar>"]}
